// src/renderer/colorBits.ts
function packAbgr(r, g, b, a) {
  return (a << 24 | b << 16 | g << 8 | r) >>> 0;
}
function abgrRed(c) {
  return c & 255;
}
function abgrGreen(c) {
  return c >>> 8 & 255;
}
function abgrBlue(c) {
  return c >>> 16 & 255;
}
function abgrAlpha(c) {
  return c >>> 24 & 255;
}
function abgrHex(c) {
  return `#${[abgrRed(c), abgrGreen(c), abgrBlue(c)].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}
function abgrToCssRgba(c) {
  return `rgba(${abgrRed(c)},${abgrGreen(c)},${abgrBlue(c)},${abgrAlpha(c) / 255})`;
}
function normalizedRgbToCssRgba(c, alpha) {
  return `rgba(${Math.round(c[0] * 255)},${Math.round(c[1] * 255)},${Math.round(c[2] * 255)},${alpha})`;
}
var FADED_ALPHA = 0.3;
function fadeAbgr(c, alpha) {
  return packAbgr(
    abgrRed(c),
    abgrGreen(c),
    abgrBlue(c),
    Math.round(abgrAlpha(c) * alpha)
  );
}
function brightenAbgr(c, factor) {
  const t = Math.max(0, 1 - 1 / factor);
  const lift = (v) => Math.round(v + (255 - v) * t);
  return packAbgr(
    lift(abgrRed(c)),
    lift(abgrGreen(c)),
    lift(abgrBlue(c)),
    abgrAlpha(c)
  );
}
function hexAbgr(hex) {
  const v = Number.parseInt(hex.slice(1), 16);
  return packAbgr(v >> 16 & 255, v >> 8 & 255, v & 255, 255);
}
var linear = (v) => {
  const s = v / 255;
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
};
function relativeLuminance(c) {
  return 0.2126 * linear(abgrRed(c)) + 0.7152 * linear(abgrGreen(c)) + 0.0722 * linear(abgrBlue(c));
}
function contrastRatio(a, b) {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}
function mixAbgr(c, to, t) {
  const mix = (a, b) => Math.round(a + (b - a) * t);
  return packAbgr(
    mix(abgrRed(c), abgrRed(to)),
    mix(abgrGreen(c), abgrGreen(to)),
    mix(abgrBlue(c), abgrBlue(to)),
    255
  );
}

export {
  packAbgr,
  abgrRed,
  abgrGreen,
  abgrBlue,
  abgrAlpha,
  abgrHex,
  abgrToCssRgba,
  normalizedRgbToCssRgba,
  FADED_ALPHA,
  fadeAbgr,
  brightenAbgr,
  hexAbgr,
  relativeLuminance,
  contrastRatio,
  mixAbgr
};
